SELECT id, order_id, product_id, quantity, unit_price, LEAD(unit_price) OVER w_hist AS next_unit_price, LAG(unit_price) OVER w_hist AS prev_unit_price, LEAD(quantity) OVER w_hist AS next_quantity, ROW_NUMBER() OVER w_hist AS event_seq, ROUND(unit_price / SUM(unit_price) OVER (PARTITION BY order_id, product_id), 4) AS unit_price_share FROM order_items WHERE order_id IN (23, 29, 32, 34) WINDOW w_hist AS (PARTITION BY product_id ORDER BY unit_price, id);
